package com.nextcandle.ai;
public final class Candle { public final double open,high,low,close,volume; public final long timestampMs; public Candle(double o,double h,double l,double c,double v,long t){open=o;high=h;low=l;close=c;volume=v;timestampMs=t;} public double range(){return Math.max(1e-9,high-low);} public double body(){return close-open;} public double bodyAbs(){return Math.abs(body());} public double upperWick(){return Math.max(0,high-Math.max(open,close));} public double lowerWick(){return Math.max(0,Math.min(open,close)-low);} public double bodyRatio(){return bodyAbs()/range();} public double closePosition(){return (close-low)/range();} public boolean bullish(){return close>open;} public boolean bearish(){return close<open;} }
